// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Sign in
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe The signed-in user and the anti-CSRF token of the session
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Change the interface language and time zone
	// (PATCH /api/v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// Setup Create the first administrator and sign in
	// (POST /api/v1/setup)
	Setup(ctx context.Context, request SetupRequestObject) (SetupResponseObject, error)
	// GetSetupStatus Whether the first administrator still has to be created
	// (GET /api/v1/setup/status)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// ListTransfers The signed-in user's transfers, newest first
	// (GET /api/v1/transfers)
	ListTransfers(ctx context.Context, request ListTransfersRequestObject) (ListTransfersResponseObject, error)
	// DeleteTransfer Remove a finished transfer from the history
	// (DELETE /api/v1/transfers/{transferId})
	DeleteTransfer(ctx context.Context, request DeleteTransferRequestObject) (DeleteTransferResponseObject, error)
	// GetTransfer One transfer
	// (GET /api/v1/transfers/{transferId})
	GetTransfer(ctx context.Context, request GetTransferRequestObject) (GetTransferResponseObject, error)
	// CancelTransfer Stop a transfer in progress
	// (POST /api/v1/transfers/{transferId}/cancel)
	CancelTransfer(ctx context.Context, request CancelTransferRequestObject) (CancelTransferResponseObject, error)
	// GetVault State of the vault in this session
	// (GET /api/v1/vault)
	GetVault(ctx context.Context, request GetVaultRequestObject) (GetVaultResponseObject, error)
	// LockVault Lock the vault for this session
	// (POST /api/v1/vault/lock)
	LockVault(ctx context.Context, request LockVaultRequestObject) (LockVaultResponseObject, error)
	// ChangeMasterPassword Change the master password
	// (POST /api/v1/vault/password)
	ChangeMasterPassword(ctx context.Context, request ChangeMasterPasswordRequestObject) (ChangeMasterPasswordResponseObject, error)
	// RecoverVault Set a new master password with the recovery kit
	// (POST /api/v1/vault/recover)
	RecoverVault(ctx context.Context, request RecoverVaultRequestObject) (RecoverVaultResponseObject, error)
	// RegenerateRecoveryKit Replace the recovery kit
	// (POST /api/v1/vault/recovery-kit)
	RegenerateRecoveryKit(ctx context.Context, request RegenerateRecoveryKitRequestObject) (RegenerateRecoveryKitResponseObject, error)
	// SetupVault Create the vault and unlock it
	// (POST /api/v1/vault/setup)
	SetupVault(ctx context.Context, request SetupVaultRequestObject) (SetupVaultResponseObject, error)
	// UnlockVault Unlock the vault for this session
	// (POST /api/v1/vault/unlock)
	UnlockVault(ctx context.Context, request UnlockVaultRequestObject) (UnlockVaultResponseObject, error)
	// ListWorkspaces Workspaces the signed-in user belongs to, with their role in each
	// (GET /api/v1/workspaces)
	ListWorkspaces(ctx context.Context, request ListWorkspacesRequestObject) (ListWorkspacesResponseObject, error)
	// GetWorkspace One workspace of the signed-in user
	// (GET /api/v1/workspaces/{workspaceId})
	GetWorkspace(ctx context.Context, request GetWorkspaceRequestObject) (GetWorkspaceResponseObject, error)
	// ListCollections Collections of a workspace
	// (GET /api/v1/workspaces/{workspaceId}/collections)
	ListCollections(ctx context.Context, request ListCollectionsRequestObject) (ListCollectionsResponseObject, error)
	// CreateCollection Create a collection
	// (POST /api/v1/workspaces/{workspaceId}/collections)
	CreateCollection(ctx context.Context, request CreateCollectionRequestObject) (CreateCollectionResponseObject, error)
	// DeleteCollection Delete an empty collection
	// (DELETE /api/v1/workspaces/{workspaceId}/collections/{collectionId})
	DeleteCollection(ctx context.Context, request DeleteCollectionRequestObject) (DeleteCollectionResponseObject, error)
	// UpdateCollection Rename or move a collection
	// (PATCH /api/v1/workspaces/{workspaceId}/collections/{collectionId})
	UpdateCollection(ctx context.Context, request UpdateCollectionRequestObject) (UpdateCollectionResponseObject, error)
	// ForgetHostKey Forget a trusted key, so the next connection asks again
	// (DELETE /api/v1/workspaces/{workspaceId}/known-hosts)
	ForgetHostKey(ctx context.Context, request ForgetHostKeyRequestObject) (ForgetHostKeyResponseObject, error)
	// ListKnownHosts Server keys trusted in a workspace
	// (GET /api/v1/workspaces/{workspaceId}/known-hosts)
	ListKnownHosts(ctx context.Context, request ListKnownHostsRequestObject) (ListKnownHostsResponseObject, error)
	// TrustHostKey Trust a server key
	// (POST /api/v1/workspaces/{workspaceId}/known-hosts)
	TrustHostKey(ctx context.Context, request TrustHostKeyRequestObject) (TrustHostKeyResponseObject, error)
	// ListQuickConnections The signed-in user's quick connections in a workspace
	// (GET /api/v1/workspaces/{workspaceId}/quick-connections)
	ListQuickConnections(ctx context.Context, request ListQuickConnectionsRequestObject) (ListQuickConnectionsResponseObject, error)
	// CreateQuickConnection Try a server without saving it
	// (POST /api/v1/workspaces/{workspaceId}/quick-connections)
	CreateQuickConnection(ctx context.Context, request CreateQuickConnectionRequestObject) (CreateQuickConnectionResponseObject, error)
	// CloseQuickConnection End a quick connection and forget its credentials
	// (DELETE /api/v1/workspaces/{workspaceId}/quick-connections/{quickId})
	CloseQuickConnection(ctx context.Context, request CloseQuickConnectionRequestObject) (CloseQuickConnectionResponseObject, error)
	// SaveQuickConnection Keep a quick connection as a site
	// (POST /api/v1/workspaces/{workspaceId}/quick-connections/{quickId}/save)
	SaveQuickConnection(ctx context.Context, request SaveQuickConnectionRequestObject) (SaveQuickConnectionResponseObject, error)
	// ListSites Sites of a workspace
	// (GET /api/v1/workspaces/{workspaceId}/sites)
	ListSites(ctx context.Context, request ListSitesRequestObject) (ListSitesResponseObject, error)
	// CreateSite Save a site
	// (POST /api/v1/workspaces/{workspaceId}/sites)
	CreateSite(ctx context.Context, request CreateSiteRequestObject) (CreateSiteResponseObject, error)
	// DeleteSite Delete a site and its secrets
	// (DELETE /api/v1/workspaces/{workspaceId}/sites/{siteId})
	DeleteSite(ctx context.Context, request DeleteSiteRequestObject) (DeleteSiteResponseObject, error)
	// GetSite One site
	// (GET /api/v1/workspaces/{workspaceId}/sites/{siteId})
	GetSite(ctx context.Context, request GetSiteRequestObject) (GetSiteResponseObject, error)
	// UpdateSite Change a site
	// (PUT /api/v1/workspaces/{workspaceId}/sites/{siteId})
	UpdateSite(ctx context.Context, request UpdateSiteRequestObject) (UpdateSiteResponseObject, error)
	// DeleteFile Delete a remote file or directory
	// (DELETE /api/v1/workspaces/{workspaceId}/sites/{siteId}/files)
	DeleteFile(ctx context.Context, request DeleteFileRequestObject) (DeleteFileResponseObject, error)
	// ListFiles List a remote directory
	// (GET /api/v1/workspaces/{workspaceId}/sites/{siteId}/files)
	ListFiles(ctx context.Context, request ListFilesRequestObject) (ListFilesResponseObject, error)
	// DownloadFile Download a remote file
	// (GET /api/v1/workspaces/{workspaceId}/sites/{siteId}/files/content)
	DownloadFile(ctx context.Context, request DownloadFileRequestObject) (DownloadFileResponseObject, error)
	// UploadFile Upload a file
	// (PUT /api/v1/workspaces/{workspaceId}/sites/{siteId}/files/content)
	UploadFile(ctx context.Context, request UploadFileRequestObject) (UploadFileResponseObject, error)
	// CreateDirectory Create a remote directory
	// (POST /api/v1/workspaces/{workspaceId}/sites/{siteId}/files/directories)
	CreateDirectory(ctx context.Context, request CreateDirectoryRequestObject) (CreateDirectoryResponseObject, error)
	// StatFile Describe a remote path
	// (GET /api/v1/workspaces/{workspaceId}/sites/{siteId}/files/entry)
	StatFile(ctx context.Context, request StatFileRequestObject) (StatFileResponseObject, error)
	// RenameFile Move or rename a remote file or directory
	// (POST /api/v1/workspaces/{workspaceId}/sites/{siteId}/files/rename)
	RenameFile(ctx context.Context, request RenameFileRequestObject) (RenameFileResponseObject, error)
	// GetHealth Liveness probe
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetReadiness Readiness probe
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

